const PsxBiosBackend SCPH1001_psx_bios_backend = {
    &SCPH1001_psx_bios_image,
    SCPH1001_psx_dispatch,
    SCPH1001_psx_dispatch_call,
    SCPH1001_psx_bios_kernel_bodies,
    SCPH1001_psx_bios_kernel_body_count,
    SCPH1001_psx_bios_kernel_patch_ranges,
    SCPH1001_psx_bios_kernel_patch_range_count,
};
